--
-- Table structure for table `properties`
--

DROP TABLE IF EXISTS `properties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `properties` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `td_number` varchar(255) NOT NULL,
  `owner_name` varchar(255) NOT NULL,
  `payor_name` varchar(255) DEFAULT NULL,
  `lot_number` varchar(255) DEFAULT NULL,
  `area` varchar(255) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `kind_of_property` varchar(100) DEFAULT NULL,
  `accountable_officer` varchar(255) DEFAULT NULL,
  `assessed_value` decimal(12,2) DEFAULT 0.00,
  `penalty` decimal(12,2) DEFAULT 0.00,
  `discount` decimal(15,2) DEFAULT 0.00,
  `or_number` varchar(255) DEFAULT NULL,
  `or_date` date DEFAULT NULL,
  `tax_year` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `pin` varchar(100) DEFAULT NULL,
  `block_number` varchar(100) DEFAULT NULL,
  `prev_td_number` varchar(100) DEFAULT NULL,
  `effectivity_date` date DEFAULT NULL,
  `barangay` varchar(100) DEFAULT NULL,
  `version` int(11) DEFAULT 1,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `archived` tinyint(1) DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_properties_td_number` (`td_number`),
  KEY `idx_properties_td_number` (`td_number`),
  KEY `idx_properties_owner_name` (`owner_name`(100)),
  KEY `idx_properties_accountable_officer` (`accountable_officer`(100)),
  KEY `idx_properties_is_deleted_td_number` (`td_number`),
  KEY `idx_barangay` (`barangay`),
  KEY `idx_pin` (`pin`),
  KEY `ix_properties_deleted_at` (`deleted_at`),
  CONSTRAINT `chk_assessed_value` CHECK (`assessed_value` >= 0),
  CONSTRAINT `chk_penalty` CHECK (`penalty` >= 0),
  CONSTRAINT `chk_discount` CHECK (`discount` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=17412 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

