--
-- Table structure for table `property_billings`
--

DROP TABLE IF EXISTS `property_billings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `property_billings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `property_id` int(11) NOT NULL,
  `tax_year` smallint(6) NOT NULL,
  `assessed_value` decimal(14,2) NOT NULL DEFAULT 0.00,
  `penalty` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `amount_paid` decimal(14,2) NOT NULL DEFAULT 0.00,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `due_date` date DEFAULT NULL,
  `last_penalty_applied_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_property_billings_property_year` (`property_id`,`tax_year`),
  UNIQUE KEY `uq_property_billings_property_tax_year` (`property_id`,`tax_year`),
  KEY `idx_property_billings_tax_year` (`tax_year`),
  KEY `idx_property_billings_is_archived` (`is_archived`),
  KEY `ix_property_billings_property_id_tax_year` (`property_id`,`tax_year`),
  CONSTRAINT `fk_property_billings_property` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`),
  CONSTRAINT `chk_property_billings_assessed_value_non_negative` CHECK (`assessed_value` >= 0),
  CONSTRAINT `chk_property_billings_penalty_non_negative` CHECK (`penalty` >= 0),
  CONSTRAINT `chk_property_billings_discount_non_negative` CHECK (`discount` >= 0),
  CONSTRAINT `chk_property_billings_amount_paid_non_negative` CHECK (`amount_paid` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=57806 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `property_billings`
--

